            //                "funding_rate": 9.288451412e-7,
            //                "id": 16,
            //                "info": "funding rate change",
            //                "margin_account": "flex",
            //                "mark_price": null,
            //                "new_average_entry_price": null,
            //                "new_balance": 0,
            //                "old_average_entry_price": null,
